      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(`${Math.ceil(player.hp)}/${Math.round(player.maxHp)}`, pad + barW / 2, hpY + 9);
      const expY = hpY + 24;
